# metros por ficha na extracao (conferencia: soma dos lances deve bater)
EXT = {3843:496.5,3844:478.2,3865:235.3,3874:314.4,3875:282,3876:666.6,3878:666.3,3882:562.5,3887:676,3888:674.7,3889:447,3891:228.2,3893:682.8,3896:725.5,3897:241.8,3899:567.3,3901:522,3902:572.4,3903:503.1,3904:512.7,3905:500,3906:492.2,3907:440.7,3908:501.7,3914:508.4,3915:523.4,3922:510.9}

ind, rows = [], []
for fid, (op, pn, last, turno, ls) in sorted(D.items()):
    soma = round(sum(q for _, q in ls), 2)
    assert abs(soma - EXT[fid]) < 0.05, (fid, soma, EXT[fid])
    loc = dt.datetime.fromisoformat(last) - dt.timedelta(hours=3)
    pals = [ls[i:i + 26] for i in range(0, len(ls), 26)]
    for n, p in enumerate(pals, 1):
        suf = '' if len(pals) == 1 else '_P%d' % n
        arq = 'PackList_%d_%d%s.pdf' % (fid, op, suf)
        d = dict(date=loc.strftime('%Y-%m-%d'), id=str(op) + ('' if len(pals) == 1 else '  .  PALLET %d' % n), pn=pn, lances=[q for _, q in p],
                 foot='Reconstruido do GMS (lances do RegistrosInspecao) - sem romaneio fisico no BD (06-08/10) - MEL-239')
        g.gravar('.', arq, d, ind, 'D_GMS_06a08', 'ficha %d pallet %d de %d' % (fid, n, len(pals)))
        rows.append([op, fid, n, ';'.join(str(i) for i, _ in p), len(p), round(sum(q for _, q in p), 2), turno,
                     last + 'Z', BASE + arq, 'RECONSTRUIDO'])

os.makedirs(g.OUT, exist_ok=True)
with open(os.path.join(g.OUT, 'packing_pallets_importar.csv'), 'w', newline='', encoding='utf-8-sig') as fh:
    w = csv.writer(fh, delimiter=';')
    w.writerow(['Title', 'FichaID', 'Pallet', 'LanceIDs', 'QtdLances', 'TotalM', 'Turno', 'DataHoraImp', 'LinkPDF', 'Obs'])
    w.writerows(rows)
with open(os.path.join(g.OUT, 'indice.csv'), 'w', newline='', encoding='utf-8-sig') as fh:
    w = csv.writer(fh, delimiter=';')
    w.writerow(['grupo', 'arquivo', 'id_pallet', 'part_number', 'lances', 'total_m', 'texto_codigo_total', 'data', 'obs'])
    w.writerows(ind)
print(len(D), 'fichas', len(rows), 'pallets/PDFs', round(sum(r[5] for r in rows), 2), 'm no total')
